export default async function next(
  { event, deal, acknowledge, resolution, pipeline, stage, owner, channel, baseId, tableId },
  ctx,
) {
  if (event.subscriptionType !== "deal.creation" || !event.dealId)
    throw Error("Expected a verified deal.creation event");
  const key =
      "deal:" +
      String(event.eventId ?? [event.subscriptionId, event.dealId, event.occurredAt].join(":")),
    p = deal?.properties;
  if (!p || !deal.id) throw Error("Missing HubSpot deal");
  const fields = {
    name: p.dealname ?? "",
    description: p.description ?? "",
    type: p.dealtype ?? "",
    stage: p.dealstage ?? "",
    amount: Number(p.amount ?? 0),
    id: String(deal.id),
  };
  if (!Number.isFinite(fields.amount)) throw Error("Invalid deal amount");
  let s = (await ctx.state.get(key)) ?? { phase: "ticket", pending: null };
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending external write " + s.pending);
    if (resolution === "confirmed") s.phase = s.phase === "ticket" ? "stage" : "done";
    s.pending = null;
    await ctx.state.set(key, s);
  }
  if (
    s.phase === "stage" &&
    !["closedwon", "presentationscheduled", "closedlost"].includes(fields.stage)
  ) {
    s.phase = "done";
    await ctx.state.set(key, s);
  }
  let phase =
    s.phase === "stage"
      ? { closedwon: "slack", presentationscheduled: "slides", closedlost: "airtable" }[
          fields.stage
        ]
      : s.phase;
  const high =
    fields.amount > 500 && fields.type === "newbusiness" && fields.stage !== "closedlost|closedwon";
  if (
    phase === "ticket" &&
    (!pipeline ||
      !stage ||
      pipeline.includes("YOUR_") ||
      stage.includes("YOUR_") ||
      (high && (!owner || owner.includes("YOUR_"))))
  )
    throw Error("Configure ticket pipeline, stage and high-priority owner");
  if (phase === "slack" && (!channel || channel.includes("YOUR_")))
    throw Error("Configure Slack channel");
  if (
    phase === "airtable" &&
    (!baseId || !tableId || baseId.includes("YOUR_") || tableId.includes("YOUR_"))
  )
    throw Error("Configure Airtable base and table");
  if (phase !== "done") {
    s.pending = key + ":" + phase;
    await ctx.state.set(key, s);
  }
  const properties = {
    subject: "Deal: " + fields.name,
    content: fields.description,
    hs_pipeline: pipeline,
    hs_pipeline_stage: stage,
    hs_ticket_priority: high ? "HIGH" : "MEDIUM",
    ...(high && owner ? { hubspot_owner_id: owner } : {}),
  };
  return {
    phase,
    key,
    channel: channel || "YOUR_CHANNEL",
    title: "Presentation for deal " + fields.name,
    text: "We successfully closed the deal " + fields.name + "!",
    records: [{ fields: { deal_name: fields.name, deal_id: fields.id, deal_type: fields.type } }],
    baseId: baseId || "YOUR_BASE",
    tableId: tableId || "YOUR_TABLE",
    ticketBody: { properties },
  };
}

