async function confirm({ key, phase, statusCode, body, id, records, ts }, ctx) {
  const s = await ctx.state.get(key);
  if (!s?.pending || s.pending !== key + ":" + phase) throw Error("Missing pending operation");
  if (phase === "ticket" && (statusCode < 200 || statusCode >= 300 || !body?.id))
    throw Error("Ticket not confirmed");
  if (phase === "slides" && !id) throw Error("Presentation not confirmed");
  if (phase === "airtable" && (!Array.isArray(records) || records.length !== 1 || !records[0].id))
    throw Error("Airtable record not confirmed");
  if (phase === "slack" && !ts) throw Error("Slack not confirmed");
  s.pending = null;
  s.phase = phase === "ticket" ? "stage" : "done";
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return confirm({ ...input, phase: "ticket" }, ctx);
}

